from pathlib import Path
import re
import json

ROOT = Path(__file__).resolve().parent.parent
index_path = ROOT / 'index.html'
s = index_path.read_text(encoding='utf-8')

css_anchor = '.usage-list{display:grid;gap:7px;margin-top:10px}'
css_extra = '''.usage-list{display:grid;gap:7px;margin-top:10px}
.maintenance-location-head{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}.maintenance-machine-list{display:grid;gap:12px}.maintenance-machine-card{border:1px solid var(--line);border-radius:14px;background:#fbfcfb;padding:14px}.maintenance-machine-card.selected{border-color:#8eb3a6;background:#f6faf8;box-shadow:0 0 0 2px rgba(44,106,88,.06)}.maintenance-machine-title{display:flex;align-items:flex-start;gap:10px;cursor:pointer}.maintenance-machine-title input{width:18px;height:18px;margin-top:2px}.maintenance-machine-title strong{display:block;font-size:14px}.maintenance-machine-title small{display:block;color:var(--muted);margin-top:3px;line-height:1.4}.maintenance-machine-fields{display:grid;grid-template-columns:180px 1fr;gap:12px;margin-top:13px;padding-top:13px;border-top:1px solid var(--line)}.maintenance-machine-fields .maintenance-work{grid-column:2}.maintenance-machine-usage{grid-column:1/-1}.maintenance-machine-usage .usage-list{margin-top:7px}.maintenance-machine-card:not(.selected) .maintenance-machine-fields{opacity:.55}@media(max-width:700px){.maintenance-machine-fields{grid-template-columns:1fr}.maintenance-machine-fields .maintenance-work{grid-column:1}.maintenance-location-head .btn{width:100%}}'''
if css_anchor not in s:
    raise SystemExit('CSS anchor niet gevonden')
s = s.replace(css_anchor, css_extra, 1)

pattern = r"function maintenanceForm\(m=\{\}\)\{.*?\nfunction showMaintenanceDetails\(id\)"
replacement = r'''function maintenanceForm(m={}){const t=m.id?(m.time||''):nowLocalTime();return `<div class="form-grid">${deviceSearchField(m.deviceId||'')}<div class="field"><label>Type onderhoud *</label><select name="type" required>${['Halfjaarlijks','Jaarlijks','Op afroep','Maandelijks'].map(x=>`<option ${m.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Datum *</label><input name="date" type="date" required value="${m.date||todayISO()}"><div class="muted" style="font-size:11px;margin-top:4px">Bij nieuwe registratie automatisch vandaag; aanpasbaar.</div></div><div class="field"><label>Uur</label><input name="time" type="time" required value="${t}"><div class="muted" style="font-size:11px;margin-top:4px">Bij nieuwe registratie automatisch het huidige uur; aanpasbaar.</div></div><div class="field"><label>Technieker</label><input name="technician" value="${esc(m.technician||'')}"></div><div class="field full"><label>Uitgevoerde werkzaamheden / notitie</label><textarea name="notes" placeholder="Reiniging, filters, dichtingen, afstelling, metingen…">${esc(m.notes||'')}</textarea></div>${usageBuilder(m.usedParts||[],true)}</div>`}
function maintenanceLocationGroups(){const groups=new Map();state.devices.filter(d=>(d.status||'Actief')==='Actief').forEach(d=>{const label=String(deviceLocationAt(d)||d.location||'').trim();const key=normalizeSearch(label);if(!label||!key)return;if(!groups.has(key))groups.set(key,{key,label,devices:[]});groups.get(key).devices.push(d)});return [...groups.values()].map(g=>({...g,devices:g.devices.sort((a,b)=>String(a.assetCode||a.model||'').localeCompare(String(b.assetCode||b.model||''),'nl',{numeric:true,sensitivity:'base'}))})).sort((a,b)=>a.label.localeCompare(b.label,'nl',{numeric:true,sensitivity:'base'}))}
function maintenanceBatchForm(){const groups=maintenanceLocationGroups(),t=nowLocalTime();return `<div class="form-grid"><div class="field full"><label>Locatie *</label><select id="maintenanceLocation" name="locationKey" required><option value="">Kies locatie…</option>${groups.map(g=>`<option value="${esc(g.key)}">${esc(g.label)} · ${g.devices.length} actief toestel${g.devices.length===1?'':'len'}</option>`).join('')}</select><div id="maintenanceLocationCount" class="muted" style="font-size:11px;margin-top:4px">Kies eerst de locatie waar het onderhoud wordt uitgevoerd.</div></div><div class="field"><label>Datum *</label><input name="date" type="date" required value="${todayISO()}"></div><div class="field"><label>Uur *</label><input name="time" type="time" required value="${t}"></div><div class="field full"><label>Technieker</label><input name="technician" placeholder="Naam technieker"></div><div class="field full"><div class="maintenance-location-head"><div><div class="section-title" style="margin-bottom:3px">Toestellen op deze locatie</div><div class="muted" style="font-size:11px">Selecteer de toestellen waarop onderhoud is uitgevoerd. Type, werkzaamheden en onderdelen worden per toestel geregistreerd.</div></div><button type="button" class="btn small" id="maintenanceSelectAll" style="display:none">Alles selecteren</button></div><div id="maintenanceLocationDevices" class="maintenance-machine-list"><div class="empty" style="padding:24px">Kies een locatie om de actieve toestellen te tonen.</div></div></div></div>`}
function maintenanceMachineCardHtml(d){const machine=[d.brand,d.model].filter(Boolean).join(' ')||'Geen toestelomschrijving',loc=deviceLocationAt(d)||d.location||'';return `<div class="maintenance-machine-card" data-maintenance-device="${esc(d.id)}"><label class="maintenance-machine-title"><input type="checkbox" class="maintenance-machine-check"><span><strong>${esc(d.assetCode||d.model||'Toestel')}</strong><small>${esc(machine)}${d.serial?' · S/N '+esc(d.serial):''}${loc?' · '+esc(loc):''}</small></span></label><div class="maintenance-machine-fields"><div class="field"><label>Type onderhoud *</label><select class="maintenance-machine-type" disabled>${['Halfjaarlijks','Jaarlijks','Op afroep','Maandelijks'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field maintenance-work"><label>Uitgevoerde werkzaamheden / notitie</label><textarea class="maintenance-machine-notes" disabled placeholder="Wat is er aan dit toestel uitgevoerd?"></textarea></div><div class="maintenance-machine-usage"><div class="section-title">Gebruikte onderdelen</div><div class="muted" style="font-size:11px;margin:-4px 0 7px">Onderdelen worden uitsluitend aan dit toestel gekoppeld.</div><div class="usage-list maintenance-device-usage-list" data-searchable="1">${usageRowHtml({partId:'',qty:1},true)}</div><button type="button" class="btn small maintenance-add-usage" disabled style="margin-top:8px">+ Onderdeelregel</button></div></div></div>`}
function setMaintenanceMachineEnabled(card,enabled){if(!card)return;card.classList.toggle('selected',enabled);card.querySelectorAll('.maintenance-machine-type,.maintenance-machine-notes,.maintenance-add-usage,.usage-search,.usage-qty,.remove-line').forEach(el=>el.disabled=!enabled)}
function initMaintenanceLocationForm(){const select=$('#maintenanceLocation'),box=$('#maintenanceLocationDevices'),count=$('#maintenanceLocationCount'),selectAll=$('#maintenanceSelectAll');if(!select||!box)return;const hideSuggestions=row=>{const menu=row?.querySelector('.usage-suggestions');if(menu)menu.classList.remove('show')};const render=()=>{const group=maintenanceLocationGroups().find(g=>g.key===select.value);if(!group){box.innerHTML='<div class="empty" style="padding:24px">Kies een locatie om de actieve toestellen te tonen.</div>';if(count)count.textContent='Kies eerst de locatie waar het onderhoud wordt uitgevoerd.';if(selectAll)selectAll.style.display='none';return}box.innerHTML=group.devices.map(maintenanceMachineCardHtml).join('');box.querySelectorAll('.maintenance-machine-card').forEach(card=>setMaintenanceMachineEnabled(card,false));if(count)count.textContent=`${group.devices.length} actief toestel${group.devices.length===1?'':'len'} op ${group.label}`;if(selectAll){selectAll.style.display='';selectAll.textContent='Alles selecteren'}};select.onchange=render;if(selectAll)selectAll.onclick=()=>{const cards=[...box.querySelectorAll('.maintenance-machine-card')],allSelected=cards.length&&cards.every(c=>c.querySelector('.maintenance-machine-check')?.checked);cards.forEach(card=>{const check=card.querySelector('.maintenance-machine-check');if(check){check.checked=!allSelected;setMaintenanceMachineEnabled(card,!allSelected)}});selectAll.textContent=allSelected?'Alles selecteren':'Alles uitvinken'};box.onchange=e=>{if(e.target.classList.contains('maintenance-machine-check')){const card=e.target.closest('.maintenance-machine-card');setMaintenanceMachineEnabled(card,e.target.checked);if(selectAll){const cards=[...box.querySelectorAll('.maintenance-machine-card')];selectAll.textContent=cards.length&&cards.every(c=>c.querySelector('.maintenance-machine-check')?.checked)?'Alles uitvinken':'Alles selecteren'}}};box.onclick=e=>{const suggestion=e.target.closest('.usage-suggestion');if(suggestion){const row=suggestion.closest('.usage-row'),part=state.parts.find(p=>p.id===suggestion.dataset.partId),input=row?.querySelector('.usage-search'),hidden=row?.querySelector('.usage-part');if(part&&input&&hidden){input.value=usagePartDisplay(part);hidden.value=part.id;hideSuggestions(row)}return}const add=e.target.closest('.maintenance-add-usage');if(add){const list=add.closest('.maintenance-machine-usage')?.querySelector('.maintenance-device-usage-list');if(list){const div=document.createElement('div');div.innerHTML=usageRowHtml({partId:'',qty:1},true);const row=div.firstElementChild;if(row){list.appendChild(row);row.querySelector('.usage-search')?.focus()}}return}if(e.target.classList.contains('remove-line'))e.target.closest('.usage-row')?.remove()};box.oninput=e=>{if(!e.target.classList.contains('usage-search'))return;const row=e.target.closest('.usage-row'),menu=row?.querySelector('.usage-suggestions'),hidden=row?.querySelector('.usage-part');if(hidden)hidden.value='';const q=e.target.value.trim();if(!menu)return;if(!q){menu.classList.remove('show');menu.innerHTML='';return}menu.innerHTML=usageSuggestionsHtml(q);menu.classList.add('show')};box.onkeydown=e=>{if(!e.target.classList.contains('usage-search'))return;const row=e.target.closest('.usage-row'),menu=row?.querySelector('.usage-suggestions');if(e.key==='Escape'){hideSuggestions(row);return}if(e.key==='Enter'&&menu?.classList.contains('show')){const first=menu.querySelector('.usage-suggestion');if(first){e.preventDefault();first.click()}}};box.onfocusout=e=>{if(e.target.classList.contains('usage-search'))setTimeout(()=>hideSuggestions(e.target.closest('.usage-row')),140)};render()}
function maintenanceBatchSelectedItems(){return $$('.maintenance-machine-card').filter(card=>card.querySelector('.maintenance-machine-check')?.checked).map(card=>({deviceId:card.dataset.maintenanceDevice,type:card.querySelector('.maintenance-machine-type')?.value||'Halfjaarlijks',notes:card.querySelector('.maintenance-machine-notes')?.value.trim()||'',usedParts:[...card.querySelectorAll('.maintenance-device-usage-list .usage-row')].map(row=>({partId:row.querySelector('.usage-part')?.value||'',qty:Number(row.querySelector('.usage-qty')?.value||1)})).filter(u=>u.partId&&u.qty>0)}))}
function checkMaintenanceBatchUsage(items){const totals={};items.forEach(item=>(item.usedParts||[]).forEach(u=>totals[u.partId]=(totals[u.partId]||0)+Number(u.qty||0)));for(const [id,qty] of Object.entries(totals)){const p=state.parts.find(x=>x.id===id);if(p&&Number(p.stock||0)<qty)return `Onvoldoende voorraad voor ${p.artNr} (${p.stock} beschikbaar, ${qty} nodig voor deze onderhoudsronde).`}return ''}
async function applyMaintenanceBatchUsage(items){const totals={};items.forEach(item=>(item.usedParts||[]).forEach(u=>totals[u.partId]=(totals[u.partId]||0)+Number(u.qty||0)));const now=new Date().toISOString(),updates=Object.entries(totals).map(([id,qty])=>{const p=state.parts.find(x=>x.id===id);return p?{...p,stock:Number(p.stock||0)-qty,updatedAt:now}:null}).filter(Boolean);if(updates.length)await putMany('parts',updates)}
async function recalcNextMaintenance(deviceId,type){if(!deviceId||!type)return;const all=await getAll('maintenance');const latest=all.filter(m=>m.deviceId===deviceId&&m.type===type&&m.date).sort((a,b)=>recordMoment(b).localeCompare(recordMoment(a)))[0];const d=(await getAll('devices')).find(x=>x.id===deviceId);if(!d)return;const key=type==='Halfjaarlijks'?'nextHalf':'nextAnnual';await put('devices',{...d,[key]:latest?addYears(latest.date,1):'',updatedAt:new Date().toISOString()})}
function openMaintenance(id){if(id){const old=state.maintenance.find(m=>m.id===id);if(!old)return;showModal('Onderhoud wijzigen',maintenanceForm(old),'Wijzigingen opslaan',async fd=>{const usage=collectUsage(),err=checkUsage(usage,old.usedParts||[]);if(err){alert(err);return}const m={...old,deviceId:val(fd,'deviceId'),type:val(fd,'type'),date:val(fd,'date'),time:val(fd,'time'),technician:val(fd,'technician'),notes:val(fd,'notes'),usedParts:usage,updatedAt:new Date().toISOString()};await applyUsage(usage,old.usedParts||[]);await put('maintenance',m);closeModal();await refresh();toast('Onderhoud gewijzigd')});setTimeout(()=>{initDeviceSearch(old.deviceId||'');initUsageControls()},0);return}const groups=maintenanceLocationGroups();if(!groups.length){toast('Geen actieve toestellen met een locatie gevonden');return}showModal('Onderhoud per locatie',maintenanceBatchForm(),'Onderhoud registreren',async fd=>{const items=maintenanceBatchSelectedItems();if(!items.length){alert('Selecteer minstens één toestel waarop onderhoud is uitgevoerd.');return}const err=checkMaintenanceBatchUsage(items);if(err){alert(err);return}const date=val(fd,'date'),time=val(fd,'time'),technician=val(fd,'technician'),now=new Date().toISOString();const records=items.map(item=>({id:uid('mnt'),deviceId:item.deviceId,type:item.type,date,time,technician,notes:item.notes,usedParts:item.usedParts,createdAt:now,updatedAt:now}));await applyMaintenanceBatchUsage(items);await putMany('maintenance',records);closeModal();await refresh();toast(`${records.length} onderhoudsregistratie${records.length===1?'':'s'} opgeslagen`)});setTimeout(initMaintenanceLocationForm,0)}
function showMaintenanceDetails(id)'''

s2, n = re.subn(pattern, lambda m: replacement, s, count=1, flags=re.S)
if n != 1:
    raise SystemExit(f'onderhoudsblok vervangen mislukt: {n}')
s = s2

if 'v1.54 • Gesplitst wijzigingslogboek' in s:
    s = s.replace('v1.54 • Gesplitst wijzigingslogboek', 'v1.55 • Onderhoud per locatie', 1)
elif 'v1.52 • Professionele basis' in s:
    s = s.replace('v1.52 • Professionele basis', 'v1.55 • Onderhoud per locatie', 1)
else:
    raise SystemExit('versielabel niet gevonden')
index_path.write_text(s, encoding='utf-8')

sw_path = ROOT / 'sw.js'
sw = sw_path.read_text(encoding='utf-8')
if 'machinepark-v1.54-audit-parts-split' not in sw:
    raise SystemExit('verwachte v1.54 cache niet gevonden')
sw_path.write_text(sw.replace('machinepark-v1.54-audit-parts-split', 'machinepark-v1.55-location-maintenance'), encoding='utf-8')

build_path = ROOT / 'scripts' / 'build-machinepark.py'
b = build_path.read_text(encoding='utf-8')
b = b.replace('    "onderhoud navigatie": "data-view=\\"maintenance\\"",', '    "onderhoud navigatie": "data-view=\\"maintenance\\"",\n    "locatiegericht onderhoud": "id=\\"maintenanceLocation\\"",\n    "onderhoud per toestel": "maintenance-machine-card",')
b = b.replace('machinepark-v1.54-audit-parts-split', 'machinepark-v1.55-location-maintenance')
build_path.write_text(b, encoding='utf-8')

test_path = ROOT / 'tests' / 'build-smoke.test.mjs'
t = test_path.read_text(encoding='utf-8')
t = t.replace("    'data-view=\"maintenance\"',", "    'data-view=\"maintenance\"',\n    'id=\"maintenanceLocation\"',\n    'maintenance-machine-card',\n    'maintenanceBatchSelectedItems',")
t = t.replace("test('service worker forceert nieuwe cache na gesplitst wijzigingslogboek', () => {\n  assert.ok(sw.includes('machinepark-v1.54-audit-parts-split'));", "test('service worker forceert nieuwe cache na locatiegericht onderhoud', () => {\n  assert.ok(sw.includes('machinepark-v1.55-location-maintenance'));")
test_path.write_text(t, encoding='utf-8')

pkg_path = ROOT / 'package.json'
pkg = json.loads(pkg_path.read_text(encoding='utf-8'))
pkg['version'] = '1.55.0'
pkg_path.write_text(json.dumps(pkg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

print('[Machinepark] locatiegericht onderhoud toegepast')
